"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"explorerSidebar":[{"type":"link","label":"Explorer Guide","href":"/docs/explorer/intro","docId":"explorer/intro","unlisted":false},{"type":"category","label":"Explorer Documentation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Explorer Full Documentation","href":"/docs/explorer/full-docs/intro","docId":"explorer/full-docs/intro","unlisted":false},{"type":"link","label":"Browsing Content","href":"/docs/explorer/full-docs/browsing","docId":"explorer/full-docs/browsing","unlisted":false},{"type":"link","label":"Using the Player","href":"/docs/explorer/full-docs/player","docId":"explorer/full-docs/player","unlisted":false},{"type":"link","label":"Preferences and Settings","href":"/docs/explorer/full-docs/settings","docId":"explorer/full-docs/settings","unlisted":false}],"href":"/docs/explorer/full-docs"}],"musicEditorSidebar":[{"type":"link","label":"Music Editor Guide","href":"/docs/music-editor/intro","docId":"music-editor/intro","unlisted":false},{"type":"category","label":"Music Editor Documentation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Music Editor Overview","href":"/docs/music-editor/full-docs/intro","docId":"music-editor/full-docs/intro","unlisted":false},{"type":"link","label":"Song Info","href":"/docs/music-editor/full-docs/song-info","docId":"music-editor/full-docs/song-info","unlisted":false},{"type":"link","label":"Lyrics","href":"/docs/music-editor/full-docs/lyrics","docId":"music-editor/full-docs/lyrics","unlisted":false},{"type":"link","label":"Timing","href":"/docs/music-editor/full-docs/timing","docId":"music-editor/full-docs/timing","unlisted":false},{"type":"link","label":"Beat Grid","href":"/docs/music-editor/full-docs/beat-grid","docId":"music-editor/full-docs/beat-grid","unlisted":false},{"type":"link","label":"Tempo Editor","href":"/docs/music-editor/full-docs/tempo-editor","docId":"music-editor/full-docs/tempo-editor","unlisted":false},{"type":"link","label":"Musical Data","href":"/docs/music-editor/full-docs/musical-data","docId":"music-editor/full-docs/musical-data","unlisted":false}],"href":"/docs/music-editor/full-docs"}],"animDesignerSidebar":[{"type":"link","label":"Anim Designer Guide","href":"/docs/anim-designer/intro","docId":"anim-designer/intro","unlisted":false},{"type":"category","label":"Anim Designer Documentation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Designer Overview","href":"/docs/anim-designer/full-docs/intro","docId":"anim-designer/full-docs/intro","unlisted":false},{"type":"link","label":"Working with Modules","href":"/docs/anim-designer/full-docs/modules","docId":"anim-designer/full-docs/modules","unlisted":false},{"type":"link","label":"Arranging the Layout","href":"/docs/anim-designer/full-docs/layout","docId":"anim-designer/full-docs/layout","unlisted":false},{"type":"link","label":"Animation Parameters","href":"/docs/anim-designer/full-docs/config-params","docId":"anim-designer/full-docs/config-params","unlisted":false}],"href":"/docs/anim-designer/full-docs"}],"developerSidebar":[{"type":"link","label":"Developer Guide","href":"/docs/developer/intro","docId":"developer/intro","unlisted":false},{"type":"category","label":"Developer Documentation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Concepts Overview","href":"/docs/developer/full-docs/intro","docId":"developer/full-docs/intro","unlisted":false},{"type":"link","label":"Getting Started","href":"/docs/developer/full-docs/getting-started","docId":"developer/full-docs/getting-started","unlisted":false},{"type":"link","label":"Event-Based System","href":"/docs/developer/full-docs/event-based-system","docId":"developer/full-docs/event-based-system","unlisted":false},{"type":"link","label":"Module Collections","href":"/docs/developer/full-docs/module-collection","docId":"developer/full-docs/module-collection","unlisted":false},{"type":"link","label":"Animation Configuration","href":"/docs/developer/full-docs/animation-config","docId":"developer/full-docs/animation-config","unlisted":false},{"type":"link","label":"G Object Reference","href":"/docs/developer/full-docs/g-object-reference","docId":"developer/full-docs/g-object-reference","unlisted":false}],"href":"/docs/developer/full-docs"}],"tutorialSidebar":[]},"docs":{"about":{"id":"about","title":"About An\u0131\u20f0mr","description":"An\u0131\u20f0mr is a platform where music and animation come together. You can sit back and watch animations play in perfect sync with songs, or get involved by contributing song data and building your own animations. Whether you just want to enjoy the experience or help create it, there is a place for you here."},"anim-designer/full-docs/config-params":{"id":"anim-designer/full-docs/config-params","title":"Animation Parameters","description":"What are animation parameters?","sidebar":"animDesignerSidebar"},"anim-designer/full-docs/intro":{"id":"anim-designer/full-docs/intro","title":"Designer Overview","description":"The Anim Designer is the visual editor for building animations on Animr. It gives you a full-screen workspace divided into two areas: a Layout Preview pane on the left (or top on mobile) and a tabbed panel on the right where you do most of your work.","sidebar":"animDesignerSidebar"},"anim-designer/full-docs/layout":{"id":"anim-designer/full-docs/layout","title":"Arranging the Layout","description":"What is a layout?","sidebar":"animDesignerSidebar"},"anim-designer/full-docs/modules":{"id":"anim-designer/full-docs/modules","title":"Working with Modules","description":"What is a module?","sidebar":"animDesignerSidebar"},"anim-designer/intro":{"id":"anim-designer/intro","title":"Anim Designer Guide","description":"Welcome! The Anim Designer is a visual tool for building animations on Animr. You pick ready-made modules, arrange how they appear on screen, and set any options you want \u2014 all without writing a single line of code.","sidebar":"animDesignerSidebar"},"developer/full-docs/animation-config":{"id":"developer/full-docs/animation-config","title":"Animation Configuration","description":"Animations can expose configurable parameters that users adjust without touching the code. You define these parameters in the animation\'s config array, and the platform renders the appropriate input controls automatically.","sidebar":"developerSidebar"},"developer/full-docs/event-based-system":{"id":"developer/full-docs/event-based-system","title":"Event-Based System","description":"Animr synchronizes your code with music through an event system. Instead of polling for the current beat or time, you register handlers and the platform calls them at precisely the right moment.","sidebar":"developerSidebar"},"developer/full-docs/g-object-reference":{"id":"developer/full-docs/g-object-reference","title":"G Object Reference","description":"The G object is passed as the first argument to your module\'s default export function. It is your module\'s interface to the platform \u2014 for event handling, DOM access, data queries, and rendering utilities.","sidebar":"developerSidebar"},"developer/full-docs/getting-started":{"id":"developer/full-docs/getting-started","title":"Getting Started","description":"This guide walks you through writing and running your first animation in the Code Playground.","sidebar":"developerSidebar"},"developer/full-docs/intro":{"id":"developer/full-docs/intro","title":"Concepts Overview","description":"Before writing your first animation it helps to understand the three building blocks of the Animr developer platform: Modules, Module Collections, and the G object.","sidebar":"developerSidebar"},"developer/full-docs/module-collection":{"id":"developer/full-docs/module-collection","title":"Module Collections","description":"A module collection is a grouping of one or more modules \u2014 or other nested collections \u2014 that share a visual layout and a common event bus. Collections are how you build multi-module animations.","sidebar":"developerSidebar"},"developer/intro":{"id":"developer/intro","title":"Developer Guide","description":"This guide is for JavaScript developers who want to build music-reactive content on the Animr platform \u2014 whether that means karaoke displays, instrument guides, rhythm games, or abstract visualizers.","sidebar":"developerSidebar"},"explorer/full-docs/browsing":{"id":"explorer/full-docs/browsing","title":"Browsing Content","description":"An\u0131\u20f0mr gives you several ways to find songs and animations. You can start from the home page, browse dedicated libraries, or search for something specific.","sidebar":"explorerSidebar"},"explorer/full-docs/intro":{"id":"explorer/full-docs/intro","title":"Explorer Full Documentation","description":"This section covers everything an Explorer can do on An\u0131\u20f0mr. Use the links below to jump to the topic you need.","sidebar":"explorerSidebar"},"explorer/full-docs/player":{"id":"explorer/full-docs/player","title":"Using the Player","description":"The player is the main experience on An\u0131\u20f0mr. An animation plays in sync with the music, and a set of controls lets you manage playback, adjust the audio, switch content, and customise the display.","sidebar":"explorerSidebar"},"explorer/full-docs/settings":{"id":"explorer/full-docs/settings","title":"Preferences and Settings","description":"Open Settings from the navigation (the gear icon) to reach the Preferences page. Your preferences are saved on this device and apply whether or not you are signed in.","sidebar":"explorerSidebar"},"explorer/intro":{"id":"explorer/intro","title":"Explorer Guide","description":"Welcome! As an Explorer, you can watch animations synced to music, discover new content, and personalise the experience to your liking. No account required to start watching.","sidebar":"explorerSidebar"},"music-editor/full-docs/beat-grid":{"id":"music-editor/full-docs/beat-grid","title":"Beat Grid","description":"The beat grid is the visual timeline at the heart of the Timing tab. It shows the song\'s full duration as a horizontal strip, with time running left to right. Every timing event you add \u2014 whether a lyric tap, a chord marker, or a section boundary \u2014 appears here as a colored marker.","sidebar":"musicEditorSidebar"},"music-editor/full-docs/intro":{"id":"music-editor/full-docs/intro","title":"Music Editor Overview","description":"The music editor is where song data is created and refined. Every beat marker, lyric line, chord, and section you add improves the experience for every animation that uses that song.","sidebar":"musicEditorSidebar"},"music-editor/full-docs/lyrics":{"id":"music-editor/full-docs/lyrics","title":"Lyrics","description":"The Lyrics tab is where you manage the text of a song\'s lyrics. This is separate from timing \u2014 you focus on getting the words right here, and connect them to the music in the Timing tab.","sidebar":"musicEditorSidebar"},"music-editor/full-docs/musical-data":{"id":"music-editor/full-docs/musical-data","title":"Musical Data","description":"The Details tab holds four types of musical annotation: Sections, Keys, Chords, and Time Signatures. These are used by animations to react to the structure and harmony of a song \u2014 for example, changing color on a chorus, or displaying chord names above the lyrics.","sidebar":"musicEditorSidebar"},"music-editor/full-docs/song-info":{"id":"music-editor/full-docs/song-info","title":"Song Info","description":"The Info tab is the first tab you see when you open a song for editing. It holds the basic facts about the song: its title, who performed it, where to find the audio or video, and its musical properties.","sidebar":"musicEditorSidebar"},"music-editor/full-docs/tempo-editor":{"id":"music-editor/full-docs/tempo-editor","title":"Tempo Editor","description":"The tempo editor is the Tempo (BPM) field in the Info tab. Getting the BPM right is the most important step in editing a song \u2014 all beat and lyric timing is built on top of it.","sidebar":"musicEditorSidebar"},"music-editor/full-docs/timing":{"id":"music-editor/full-docs/timing","title":"Timing","description":"The Timing tab is where you connect your lyrics to the music. You stamp each lyric line with the exact moment it starts in the song, so animations know when to display or highlight each line.","sidebar":"musicEditorSidebar"},"music-editor/intro":{"id":"music-editor/intro","title":"Music Editor Guide","description":"Welcome! This guide is for anyone who wants to help add song data to Animr \u2014 no technical background required. If you know a song well enough to recognize its lyrics and feel its beat, you can contribute.","sidebar":"musicEditorSidebar"}}}}')}}]);